import unittest

from report import report_time


class ReportTimeTests(unittest.TestCase):
    def test_converts_utc_to_report_timezone(self):
        self.assertEqual(
            report_time("2024-01-15T10:30:00Z"),
            "2024-01-15 18:30",
        )

    def test_handles_offset_and_crossing_midnight(self):
        self.assertEqual(
            report_time("2024-01-15T23:30:00-05:00"),
            "2024-01-16 12:30",
        )

    def test_discards_seconds_and_microseconds(self):
        self.assertEqual(
            report_time("2024-06-01T12:34:56.789+08:00"),
            "2024-06-01 12:34",
        )

    def test_rejects_naive_timestamp(self):
        with self.assertRaises(ValueError):
            report_time("2024-01-15T10:30:00")


if __name__ == "__main__":
    unittest.main()
